'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { HrmsProvider, useHrms } from '@/context/hrms-context';
import { APP_SECTIONS } from '@/lib/hrms-sections';
import { cn } from '@/lib/utils';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import {
  LayoutDashboard, Shield, Users, CalendarCheck,
  Building2, UtensilsCrossed, Calendar, Image,
  FileText, Package, BarChart2, UserCog, Settings,
} from 'lucide-react';
import type { SectionKey } from '@/types/hrms';

const SECTION_ICONS: Record<SectionKey, React.ComponentType<{ className?: string }>> = {
  dashboard: LayoutDashboard,
  reservations: CalendarCheck,
  guests: Users,
  accommodations: Building2,
  dining: UtensilsCrossed,
  events: Calendar,
  gallery: Image,
  blogs: FileText,
  inventory: Package,
  reports: BarChart2,
  hrms: UserCog,
  settings: Settings,
};

const HRMS_NAV = [
  { href: '/hrms', label: 'Dashboard', icon: LayoutDashboard, exact: true },
  { href: '/hrms/roles', label: 'Roles & Permissions', icon: Shield, exact: false },
  { href: '/hrms/employees', label: 'Employees', icon: Users, exact: false },
];

function Sidebar() {
  const pathname = usePathname();
  const { employees, viewAsEmployeeId, setViewAsEmployeeId } = useHrms();

  const viewingEmployee = viewAsEmployeeId
    ? employees.find(e => e.id === viewAsEmployeeId)
    : null;

  const permittedSections = viewingEmployee ? viewingEmployee.customPermissions : null;

  const visibleSections = permittedSections === null
    ? APP_SECTIONS
    : APP_SECTIONS.filter(s => permittedSections.includes(s.key));

  const isActive = (href: string, exact: boolean) =>
    exact ? pathname === href : pathname.startsWith(href);

  return (
    <aside className="w-64 flex flex-col bg-card border-r border-border overflow-y-auto shrink-0">
      <div className="px-4 py-5 border-b border-border">
        <p className="text-[10px] text-muted-foreground uppercase tracking-widest mb-0.5">Oruthota Chalets</p>
        <h1 className="text-base font-semibold">HR Portal</h1>
      </div>

      <div className="px-3 py-3 border-b border-border">
        <p className="text-xs text-muted-foreground mb-1.5">Preview as employee</p>
        <Select
          value={viewAsEmployeeId ?? 'admin'}
          onValueChange={v => setViewAsEmployeeId(v === 'admin' ? null : v)}
        >
          <SelectTrigger className="h-8 text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="admin">Admin — all sections</SelectItem>
            {employees.map(e => (
              <SelectItem key={e.id} value={e.id}>
                {e.firstName} {e.lastName}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {viewingEmployee && (
          <p className="text-xs text-amber-400 mt-1.5">
            {permittedSections?.length ?? 0} permitted section{permittedSections?.length !== 1 ? 's' : ''}
          </p>
        )}
      </div>

      {!viewingEmployee && (
        <div className="px-3 py-3 border-b border-border">
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
            HR Management
          </p>
          <nav className="space-y-0.5">
            {HRMS_NAV.map(({ href, label, icon: Icon, exact }) => (
              <Link
                key={href}
                href={href}
                className={cn(
                  'flex items-center gap-2.5 px-3 py-2 rounded-md text-sm transition-colors',
                  isActive(href, exact)
                    ? 'bg-primary/10 text-primary font-medium'
                    : 'text-muted-foreground hover:text-foreground hover:bg-accent'
                )}
              >
                <Icon className="h-4 w-4 shrink-0" />
                {label}
              </Link>
            ))}
          </nav>
        </div>
      )}

      <div className="px-3 py-3 flex-1">
        <div className="flex items-center justify-between mb-1.5">
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
            Portal Sections
          </p>
          {permittedSections !== null && (
            <Badge variant="secondary" className="text-[10px] px-1.5 h-4">
              {permittedSections.length}/{APP_SECTIONS.length}
            </Badge>
          )}
        </div>
        <nav className="space-y-0.5">
          {visibleSections.map(section => {
            const Icon = SECTION_ICONS[section.key];
            return (
              <Link
                key={section.key}
                href={section.path}
                className="flex items-center gap-2.5 px-3 py-2 rounded-md text-sm text-muted-foreground hover:text-foreground hover:bg-accent transition-colors"
              >
                <Icon className="h-4 w-4 shrink-0" />
                {section.label}
              </Link>
            );
          })}
          {visibleSections.length === 0 && (
            <p className="px-3 py-2 text-xs text-muted-foreground italic">No sections assigned</p>
          )}
        </nav>
      </div>

      <div className="px-4 py-3 border-t border-border">
        <Link href="/" className="text-xs text-muted-foreground hover:text-foreground transition-colors">
          ← Back to site
        </Link>
      </div>
    </aside>
  );
}

function HrmsLayoutInner({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex h-screen bg-background overflow-hidden">
      <Sidebar />
      <main className="flex-1 overflow-auto">
        {children}
      </main>
    </div>
  );
}

export default function HrmsLayout({ children }: { children: React.ReactNode }) {
  return (
    <HrmsProvider>
      <HrmsLayoutInner>{children}</HrmsLayoutInner>
    </HrmsProvider>
  );
}
